// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address caller, address newOwner) public {
        address originalOwner = c.owner();
        vm.assume(caller != originalOwner);
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            // In the correct contract a non-owner cannot transfer ownership;
            // ownership must remain unchanged.
            assertTrue(c.owner() == originalOwner);
        } catch {
            // Correct behavior: the call reverts for non-owners and ownership is unchanged.
            assertTrue(c.owner() == originalOwner);
        }
    }
}
